import { ApiProperty } from "@nestjs/swagger";
import { IsString, MinLength } from "class-validator";

export class ConfirmPaymentDto {
  @ApiProperty({
    example:
      "data:image/jpeg;base64,",
    description: "Bank transfer receipt image as a base64 data URL",
  })
  @IsString()
  @MinLength(32)
  receiptImage!: string;
}
